    pub(crate) fn incremental_glyph_data(&self, glyph_index: u16) -> Option<&[u8]> {
        let data = &self.font.data;
        let location = loca::get_glyph_location(
            &data.loca_data,
            glyph_index,
            data.head.index_to_loc_format,
            data.glyf_data.len(),
        )?;
        let start = usize::try_from(location.offset).ok()?;
        let end = start.checked_add(usize::try_from(location.length).ok()?)?;
        data.glyf_data.get(start..end)
    }

