        font: &Font,
        glyph_index: u16,
        mut flags: LoadFlags,
        transform: Option<(i32, i32, i32, i32, i32, i32)>,
    ) -> Result<GlyphSlot, FontError> {
        flags = Self::normalize_load_flags(font, flags);
        if font.sbix_active_strike_is_unmatched() {
            // `ttdriver.c:tt_size_request` retains Invalid_Pixel_Size when
            // `set_sbit_strike` cannot select a fixed sbix strike.  Model the
            // load-time result here because the public C sequence continues
            // after that setup return; all ABI facades share this guard.
            return Err(FontError::InvalidPixelSize);
        }
        let transform = if flags.contains(LoadFlags::NO_RECURSE) {
            None
        } else {
            transform
        };
        let vertical_layout = flags.contains(LoadFlags::VERTICAL_LAYOUT);
        let native_hint_mode = flags.native_hint_mode();

fn normalize_load_flags(font: &Font, mut flags: LoadFlags) -> LoadFlags {
        let metrics = font.size_metrics();
        // FreeType resolves these dependencies in `FT_Load_Glyph` before driver
        // load (`src/base/ftobjs.c:932-952`).  Keep this in core so Rust, C ABI,
        // and WASM public entry points all exercise the same policy.
        if metrics.x_ppem == 0 || metrics.y_ppem == 0 {
            flags |= LoadFlags::NO_SCALE;
        }
        if flags.contains(LoadFlags::NO_RECURSE) {
            flags |= LoadFlags::NO_SCALE;
        }
        if flags.contains(LoadFlags::NO_SCALE) {
            flags |= LoadFlags::NO_HINTING | LoadFlags::NO_BITMAP;
            flags = flags.without(LoadFlags::RENDER);
        }
        if flags.contains(LoadFlags::BITMAP_METRICS_ONLY) {
            flags = flags.without(LoadFlags::RENDER);
        }
        flags
    }

fn load_glyph_from_font(
        font: &Font,
        glyph_index: u16,
        mut flags: LoadFlags,
        transform: Option<(i32, i32, i32, i32, i32, i32)>,
    ) -> Result<GlyphSlot, FontError> {
        flags = Self::normalize_load_flags(font, flags);
        if font.sbix_active_strike_is_unmatched() {
            // `ttdriver.c:tt_size_request` retains Invalid_Pixel_Size when
            // `set_sbit_strike` cannot select a fixed sbix strike.  Model the
            // load-time result here because the public C sequence continues
            // after that setup return; all ABI facades share this guard.
            return Err(FontError::InvalidPixelSize);
        }
        let transform = if flags.contains(LoadFlags::NO_RECURSE) {
            None
        } else {
            transform
        };
        let vertical_layout = flags.contains(LoadFlags::VERTICAL_LAYOUT);
        let native_hint_mode = flags.native_hint_mode();

let pedantic_hinting = flags.contains(LoadFlags::PEDANTIC);
let sbits_only = flags.contains(LoadFlags::SBITS_ONLY);
let svg_only = flags.contains(LoadFlags::SVG_ONLY);
let svg_allowed = flags.contains(LoadFlags::COLOR) && !flags.contains(LoadFlags::NO_SVG);
// `TT_Load_Glyph` converts a missing image from a non-scalable sbix
// face into a successful empty MONO bitmap before trying outlines.
// This must precede the outline path because bitmap-only sbix faces
// intentionally do not expose a usable scalable glyph there.
if let Some(sbit) = font.sbix_missing_bitmap_glyph(glyph_index, font.size_metrics().y_ppem)
{
    let mut slot = empty_sbit_glyph_slot(glyph_index, sbit, vertical_layout);
    if let Some((xx, xy, yx, yy, dx, dy)) = transform {
        slot.apply_transform(xx, xy, yx, yy, dx, dy);
    }
    return Ok(slot);
}
if svg_allowed {

    match font.load_svg_glyph(glyph_index) {
        Ok((metrics, document)) => {
            let mut slot =
                GlyphSlot::from_svg(glyph_index, metrics, document, vertical_layout);
            if let Some((xx, xy, yx, yy, dx, dy)) = transform {
                slot.apply_transform(xx, xy, yx, yy, dx, dy);
            }
            return Ok(slot);
        }
        Err(_) if svg_only => {
            return Err(FontError::InvalidArgument("SVG glyph not available".into()));
        }
        Err(_) => {}
    }
} else if svg_only {
    return Err(FontError::InvalidArgument("SVG glyph not available".into()));
}
// C `truetype/ttgload.c:TT_Load_Glyph` only honors `FT_LOAD_NO_BITMAP`
// for scalable faces: `!(NO_BITMAP && FT_IS_SCALABLE(face))`.  For
// bitmap-only CBLC/CBDT faces, `sfobjs.c` clears SCALABLE and the

// embedded strike is therefore loaded even with `FT_LOAD_NO_BITMAP`.
let sbit_allowed = !(flags.contains(LoadFlags::NO_SCALE)
    || flags.contains(LoadFlags::NO_BITMAP) && font.is_scalable());
if sbits_only && !sbit_allowed {
    return Err(FontError::InvalidArgument(
        "embedded bitmap strike not selected".into(),
    ));
}
if sbit_allowed {
    // C `FT_Load_Glyph` first tries SVG, then embedded bitmaps before
    // outline loading (`base/ftobjs.c:1028-1050`). The TrueType driver
    // repeats that SBIT attempt in `truetype/ttgload.c:2401-2474`.
    match font.load_sbit_only_glyph(glyph_index) {
        Ok(mut sbit) => {
            // `FT_LOAD_BITMAP_METRICS_ONLY` lets the SBIT loader fill
            // metrics and bitmap metadata but skips allocating the
            // image buffer (`sfnt/ttsbit.c:545-588`).

            if !flags.contains(LoadFlags::COLOR)
                && !flags.contains(LoadFlags::BITMAP_METRICS_ONLY)
            {
                sbit.bitmap.flatten_bgra_to_gray()?;
            }
            return Ok(sbit_glyph_slot_with_bitmap(
                glyph_index,
                sbit,
                vertical_layout,
                !flags.contains(LoadFlags::BITMAP_METRICS_ONLY),
            ));
        }
        Err(_) if sbits_only => {
            // For scalable TrueType faces with `FT_LOAD_SBITS_ONLY`,
            // failed SBIT loading is replaced with Invalid_Argument
            // (`truetype/ttgload.c:2467-2474`).
            return Err(FontError::InvalidArgument(
                "embedded bitmap image not available".into(),
            ));
        }
        Err(_) => {}
    }
}

